const decision_data = msg.payload.decision_output;

// فحص أمان أساسي للتأكد من وجود البيانات
if (!decision_data || !decision_data.status) {
    // إذا كانت البيانات مفقودة، نرسل الرسالة الأصلية إلى المخرج الثاني ونحذر
    node.warn("Decision data is missing. Skipping oneM2M formatting.");
    return [null, msg];
}

// استخلاص حالة القرار
// نستخدم String() لضمان أن القيمة نصية قبل استخدام .trim()
const decision_status = String(decision_data.status).trim();

// 2. التحقق من حالة الفشل الحرج (CRITICAL)
if (decision_status === "CRITICAL FAILURE IMMINENT") {

    // صياغة رسالة oneM2M: استخلاص البيانات الضرورية
    const component_code = decision_data.component;
    const arrival_port = "DXB";

    // نستخدم كائن رسالة جديد لتجنب إتلاف الرسالة الأصلية
    let oneM2M_msg = {
        payload: {
            "oneM2M_Operation": "CREATE",
            "Resource_ID": "AE-GreenBox-FLT747_3",
            "Target_Logistics_HUB": "CSE-Logistics-HUB-DMM",
            "Delivery_Payload": {
                "Part_Code": component_code,
                "Status": "Critical_Fail_48H",
                "ETA_Port": arrival_port
            }
        },
        topic: "logistics_critical" // إضافة موضوع للمساعدة في التوجيه
    };

    // إرسال رسالة oneM2M المصاغة إلى المخرج الأول (مسار اللوجستيات)
    return [oneM2M_msg, null];
}

// 3. أي حالة أخرى (WARNING أو OK) تذهب إلى المخرج الثاني
else {
    // إرسال الرسالة الأصلية (التي تحتوي على status: "WARNING..." أو "OK") إلى المخرج الثاني للمراقبة
    return [null, msg];
}

// استخراج القراءات التي نريد عرضها
var readings = msg.payload.readings;

// 2. فحص الأمان
if (!readings) {
    return [null, null, null]; // إيقاف المخارج إذا لم توجد قراءات
}

// 3. إعداد المخارج الثلاثة
var temp_out = { payload: readings.temp };
var vib_out = { payload: readings.vib };
var press_out = { payload: readings.pressure };

// 4. الإرجاع لتغذية الـ Gauges
return [temp_out, vib_out, press_out]

let temp = msg.payload.temp ;
let vib = msg.payload.vib ;
let pressure = msg.payload.pressure ;

let decision = {};

// 2. **منطق القرار (Green Box Logic):**
// هذا الجزء يبقى كما هو (وهو صحيح منطقياً)

// المستوى الأول: الفشل الحرج
if (temp > 70 && vib > 10) {
    decision = {
        status: "CRITICAL FAILURE IMMINENT",
        component: "Hydraulic_Pump_A402",
        priority: "URGENT_REPLACEMENT"
    };

    // المستوى الثاني: التحذير
} else if (temp > 50 || vib > 7 || pressure < 600) {

    let warning_list = [];

    if (temp > 50) { warning_list.push("ارتفاع الحرارة"); }
    if (vib > 7) { warning_list.push("ارتفاع الاهتزاز"); }
    if (pressure < 600) { warning_list.push("انخفاض الضغط"); }

    let status_message = "WARNING - " + warning_list.join(" و ");

    decision = {
        status: status_message,
        component: "N/A",
        priority: "ENGINEER_ALERT"
    };

    // المستوى الثالث: الحالة العادية
} else {
    decision = {
        status: "OK",
        priority: "NORMAL_MONITORING"
    };
}

// 3. **دمج الرسالة النهائية (مخرج واحد):**
msg.payload = {
    readings: {
        temp: temp,
        vib: vib,
        pressure: pressure
    },
    decision_output: decision
};

// **إرجاع الرسالة الموحدة**
return msg;
